import { describe, it, expect, beforeAll, afterAll } from '@jest/globals';
import { v4 as uuidv4 } from 'uuid';
import { pool } from '../../src/core/database/pool';
// ⚠️ REMOVIDO: split-engine.service foi deprecado e removido do projeto
// TODO: Migrar testes para @core/economy/split.service
import { transactionService } from '../../src/core/economy/transactions/transaction.service';
import { accountService } from '../../src/core/economy/accounts/account.service';
import { groupAccountService } from '../../src/core/economy/group-account.service';
import { resolveGlobalUserId } from '../../src/core/identity/identity.utils';

// ⚠️ TESTES DESATIVADOS: Estes testes precisam ser migrados para @core/economy/split.service
describe.skip('Split Engine - Integração (DEPRECADO - precisa migração)', () => {
  const testTenantId = uuidv4();
  let testFromUserId: string;
  let testToUserId: string;
  let testFromGlobalUserId: string;
  let testToGlobalUserId: string;
  let testGroupId: string;
  let testFromAccountId: string;
  let testToAccountId: string;
  let testGroupAccountId: string;

  beforeAll(async () => {
    // Criar tenant de teste
    await pool.query(
      `INSERT INTO tenants (tenant_id, name, city_id)
       VALUES ($1, 'Test Tenant', NULL)
       ON CONFLICT (tenant_id) DO NOTHING`,
      [testTenantId]
    );

    // Criar usuários de teste
    testFromUserId = uuidv4();
    testToUserId = uuidv4();
    testFromGlobalUserId = uuidv4();
    testToGlobalUserId = uuidv4();

    await pool.query(
      `INSERT INTO global_users (global_user_id, full_name, created_at)
       VALUES ($1, 'Test From User', now()), ($2, 'Test To User', now())
       ON CONFLICT (global_user_id) DO NOTHING`,
      [testFromGlobalUserId, testToGlobalUserId]
    );

    await pool.query(
      `INSERT INTO users (user_id, tenant_id, email, global_user_id, created_at)
       VALUES ($1, $2, 'from@test.com', $3, now()), ($4, $2, 'to@test.com', $5, now())
       ON CONFLICT (user_id) DO NOTHING`,
      [testFromUserId, testTenantId, testFromGlobalUserId, testToUserId, testToGlobalUserId]
    );

    // Criar grupo de teste
    testGroupId = uuidv4();
    await pool.query(
      `INSERT INTO groups (group_id, tenant_id, owner_user_id, name, description, is_active, created_at)
       VALUES ($1, $2, $3, 'Test Group', 'Test Description', true, now())
       ON CONFLICT (group_id) DO NOTHING`,
      [testGroupId, testTenantId, testFromUserId]
    );

    // Criar contas
    const fromAccount = await accountService.getOrCreateUserPrimaryAccount(
      testTenantId,
      testFromUserId,
      'BRL'
    );
    testFromAccountId = fromAccount.accountId;

    const toAccount = await accountService.getOrCreateUserPrimaryAccount(
      testTenantId,
      testToUserId,
      'BRL'
    );
    testToAccountId = toAccount.accountId;

    // Criar conta de grupo
    testGroupAccountId = await groupAccountService.createOrGetGroupAccount(
      testTenantId,
      testGroupId
    );

    // Adicionar saldo inicial
    await pool.query(
      `UPDATE accounts SET balance = 1000 WHERE account_id = $1`,
      [testFromAccountId]
    );
  });

  afterAll(async () => {
    // Limpar dados de teste
    try {
      await pool.query(`DELETE FROM transactions WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM ledger WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM accounts WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM groups WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM users WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM tenants WHERE tenant_id = $1`, [testTenantId]);
    } catch (error) {
      // Ignorar erros de limpeza
    }
  });

  describe('Split simples', () => {
    it('deve aplicar split 70% group / 30% regional', async () => {
      // Criar transação base
      const baseAmount = 100;
      const baseEventId = uuidv4();
      const baseTransfer = await transactionService.transfer(testTenantId, {
        fromAccount: testFromAccountId,
        toAccount: testToAccountId,
        amount: baseAmount,
        eventId: baseEventId,
        metadata: {
          type: 'donation',
          targetType: 'group',
          targetId: testGroupId,
        },
      });

      // Aplicar split
      const splitResult = await splitEngineService.applySplit({
        baseTransactionId: baseTransfer.transaction.transactionId,
        amount: baseAmount,
        context: 'donation',
        metadata: {
          targetType: 'group',
          targetId: testGroupId,
          fromUserId: testFromUserId,
          globalUserId: testFromGlobalUserId, // OBRIGATÓRIO
        },
        tenantId: testTenantId,
      });

      expect(splitResult).toBeDefined();
      expect(splitResult.splitGroupId).toBeDefined();
      expect(splitResult.baseTransactionId).toBe(baseTransfer.transaction.transactionId);
      expect(splitResult.totalAmount).toBe(baseAmount);
      expect(splitResult.entries.length).toBeGreaterThan(0);

      // Verificar que soma dos splits = amount original
      const totalSplit = splitResult.entries.reduce((sum, e) => sum + e.amount, 0);
      expect(Math.abs(totalSplit - baseAmount)).toBeLessThan(0.01); // Tolerância para arredondamento
    });
  });

  describe('Validação de regra', () => {
    it('deve rejeitar split com soma != 100%', async () => {
      // Isso é testado internamente na validação da regra
      // Por enquanto, as regras padrão já somam 100%
      // Este teste valida que a validação funciona
      expect(true).toBe(true); // Placeholder - validação está no código
    });
  });

  describe('Atomicidade total', () => {
    it('deve fazer rollback total se um split falhar', async () => {
      const baseAmount = 60;
      const baseEventId = uuidv4();

      // Criar transação base
      const baseTransfer = await transactionService.transfer(testTenantId, {
        fromAccount: testFromAccountId,
        toAccount: testToAccountId,
        amount: baseAmount,
        eventId: baseEventId,
        metadata: { type: 'test' },
      });

      // Tentar aplicar split sem globalUserId (deve falhar na resolução de regional_fund)
      await expect(
        splitEngineService.applySplit({
          baseTransactionId: baseTransfer.transaction.transactionId,
          amount: baseAmount,
          context: 'donation',
          metadata: {
            targetType: 'group',
            targetId: testGroupId,
            // SEM globalUserId - deve falhar
          },
          tenantId: testTenantId,
        })
      ).rejects.toThrow('globalUserId is required');

      // Verificar que NENHUM split foi criado (rollback total)
      const splitTransactions = await pool.query<{ count: string }>(
        `
        SELECT COUNT(*)::text as count
        FROM transactions
        WHERE tenant_id = $1
          AND metadata->>'type' = 'split'
          AND metadata->>'originTransactionId' = $2
        `,
        [testTenantId, baseTransfer.transaction.transactionId]
      );

      const count = parseInt(splitTransactions.rows[0]?.count || '0', 10);
      expect(count).toBe(0); // Nenhum split criado
    });
  });

  describe('Regional fund obrigatório', () => {
    it('deve falhar se globalUserId não for fornecido', async () => {
      const baseAmount = 35;
      const baseEventId = uuidv4();

      // Criar transação base
      const baseTransfer = await transactionService.transfer(testTenantId, {
        fromAccount: testFromAccountId,
        toAccount: testToAccountId,
        amount: baseAmount,
        eventId: baseEventId,
        metadata: { type: 'test' },
      });

      // Tentar aplicar split sem globalUserId
      await expect(
        splitEngineService.applySplit({
          baseTransactionId: baseTransfer.transaction.transactionId,
          amount: baseAmount,
          context: 'donation',
          metadata: {
            targetType: 'group',
            targetId: testGroupId,
            // SEM globalUserId
          },
          tenantId: testTenantId,
        })
      ).rejects.toThrow('globalUserId is required');
    });
  });

  describe('Ledger balanceado', () => {
    it('deve manter ledger balanceado após split', async () => {
      const baseAmount = 50;
      const baseEventId = uuidv4();

      // Criar transação base
      const baseTransfer = await transactionService.transfer(testTenantId, {
        fromAccount: testFromAccountId,
        toAccount: testToAccountId,
        amount: baseAmount,
        eventId: baseEventId,
        metadata: { type: 'test' },
      });

      // Aplicar split
      await splitEngineService.applySplit({
        baseTransactionId: baseTransfer.transaction.transactionId,
        amount: baseAmount,
        context: 'donation',
        metadata: {
          targetType: 'group',
          targetId: testGroupId,
          globalUserId: testFromGlobalUserId, // OBRIGATÓRIO
        },
        tenantId: testTenantId,
      });

      // Verificar ledger
      const ledgerResult = await pool.query<{ total_debits: string; total_credits: string }>(
        `
        SELECT 
          COALESCE(SUM(CASE WHEN entry_type = 'debit' THEN amount ELSE 0 END), 0)::text as total_debits,
          COALESCE(SUM(CASE WHEN entry_type = 'credit' THEN amount ELSE 0 END), 0)::text as total_credits
        FROM ledger
        WHERE tenant_id = $1
        `,
        [testTenantId]
      );

      const totalDebits = parseFloat(ledgerResult.rows[0]?.total_debits || '0');
      const totalCredits = parseFloat(ledgerResult.rows[0]?.total_credits || '0');

      // Ledger deve estar balanceado
      expect(Math.abs(totalDebits - totalCredits)).toBeLessThan(0.01);
    });
  });

  describe('Idempotência determinística', () => {
    it('deve garantir idempotência com retry do mesmo originTransactionId', async () => {
      const baseAmount = 30;
      const baseEventId = uuidv4();

      // Criar transação base
      const baseTransfer = await transactionService.transfer(testTenantId, {
        fromAccount: testFromAccountId,
        toAccount: testToAccountId,
        amount: baseAmount,
        eventId: baseEventId,
        metadata: { type: 'test' },
      });

      // Primeira aplicação de split
      const result1 = await splitEngineService.applySplit({
        baseTransactionId: baseTransfer.transaction.transactionId,
        amount: baseAmount,
        context: 'donation',
        metadata: {
          targetType: 'group',
          targetId: testGroupId,
          globalUserId: testFromGlobalUserId, // OBRIGATÓRIO
        },
        tenantId: testTenantId,
      });

      // Segunda aplicação com mesmo baseTransactionId deve retornar os mesmos splits
      // (idempotência determinística via eventId hash)
      const result2 = await splitEngineService.applySplit({
        baseTransactionId: baseTransfer.transaction.transactionId,
        amount: baseAmount,
        context: 'donation',
        metadata: {
          targetType: 'group',
          targetId: testGroupId,
          globalUserId: testFromGlobalUserId,
        },
        tenantId: testTenantId,
      });

      // Deve ter o mesmo número de entries (não duplicou)
      expect(result2.entries.length).toBe(result1.entries.length);
      
      // Verificar que não criou transações duplicadas
      const transactionIds1 = new Set(result1.entries.map(e => e.transactionId));
      const transactionIds2 = new Set(result2.entries.map(e => e.transactionId));
      
      // Todos os transactionIds devem ser iguais (idempotência)
      expect(transactionIds1.size).toBe(transactionIds2.size);
      for (const txId of transactionIds1) {
        expect(transactionIds2.has(txId)).toBe(true);
      }
    });
  });

  describe('Compensação', () => {
    it('deve criar transação inversa correta', async () => {
      const baseAmount = 40;
      const baseEventId = uuidv4();

      // Criar transação base
      const baseTransfer = await transactionService.transfer(testTenantId, {
        fromAccount: testFromAccountId,
        toAccount: testToAccountId,
        amount: baseAmount,
        eventId: baseEventId,
        metadata: { type: 'test' },
      });

      // Aplicar split
      const splitResult = await splitEngineService.applySplit({
        baseTransactionId: baseTransfer.transaction.transactionId,
        amount: baseAmount,
        context: 'donation',
        metadata: {
          targetType: 'group',
          targetId: testGroupId,
          globalUserId: testFromGlobalUserId, // OBRIGATÓRIO
        },
        tenantId: testTenantId,
      });

      // Compensar
      const compensation = await splitEngineService.compensateTransaction({
        originTransactionId: baseTransfer.transaction.transactionId,
        reason: 'Test compensation',
        tenantId: testTenantId,
      });

      expect(compensation).toBeDefined();
      expect(compensation.originTransactionId).toBe(baseTransfer.transaction.transactionId);
      expect(compensation.compensationTransactionId).toBeDefined();
      expect(compensation.reversedEntries.length).toBeGreaterThan(0);

      // Verificar que compensação inverteu valores
      const compensationTx = await pool.query<{ from_account_id: string; to_account_id: string; amount: string }>(
        `
        SELECT from_account_id, to_account_id, amount
        FROM transactions
        WHERE transaction_id = $1
        LIMIT 1
        `,
        [compensation.compensationTransactionId]
      );

      expect(compensationTx.rows[0]?.from_account_id).toBe(baseTransfer.transaction.toAccount);
      expect(compensationTx.rows[0]?.to_account_id).toBe(baseTransfer.transaction.fromAccount);
    });
  });

  describe('Metadados completos', () => {
    it('deve registrar metadados completos no ledger', async () => {
      const baseAmount = 25;
      const baseEventId = uuidv4();

      // Criar transação base
      const baseTransfer = await transactionService.transfer(testTenantId, {
        fromAccount: testFromAccountId,
        toAccount: testToAccountId,
        amount: baseAmount,
        eventId: baseEventId,
        metadata: { type: 'test' },
      });

      // Aplicar split
      const splitResult = await splitEngineService.applySplit({
        baseTransactionId: baseTransfer.transaction.transactionId,
        amount: baseAmount,
        context: 'donation',
        metadata: {
          targetType: 'group',
          targetId: testGroupId,
          globalUserId: testFromGlobalUserId, // OBRIGATÓRIO
        },
        tenantId: testTenantId,
      });

      // Verificar metadados nas transações de split
      for (const entry of splitResult.entries) {
        const tx = await pool.query<{ metadata: any }>(
          `
          SELECT metadata
          FROM transactions
          WHERE transaction_id = $1
          LIMIT 1
          `,
          [entry.transactionId]
        );

        const metadata = tx.rows[0]?.metadata;
        expect(metadata).toBeDefined();
        expect(metadata.type).toBe('split');
        expect(metadata.originTransactionId).toBe(baseTransfer.transaction.transactionId);
        expect(metadata.splitGroupId).toBe(splitResult.splitGroupId);
        expect(metadata.targetType).toBeDefined();
      }
    });
  });
});




























